int F[4][4][256][256];
ll f(ll x, ll y) {
    if (!x || !y) return 0;
    if (x == 1 || y == 1) return x * y;
    ll ans = 0;
    for (int i = 0; (1ll << i) <= x; i++)
        if (x & (1ll << i))
            for (int j = 0; (1ll << j) <= y; j++)
                if (y & (1ll << j))
                    ans ^= G[i][j];
    return ans;
}
ll nim_mul(ll x, ll y) {
    ll a[4] = {x & 255, (x >> 8) & 255, (x >> 16) & 255, (x >> 24) & 255};
    ll b[4] = {y & 255, (y >> 8) & 255, (y >> 16) & 255, (y >> 24) & 255};
    ll ans = 0;
    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 4; j++)
            ans = ans ^ F[i][j][a[i]][b[j]];
    return ans;
}
unsigned int SA, SB, SC;
unsigned int rng() {
    SA ^= SA << 16;
    SA ^= SA >> 5;
    SA ^= SA << 1;
    unsigned int t = SA;
    SA = SB;
    SB = SC;
    SC ^= t ^ SA;
    return SC;
}
int main() {
    for (int x = 0; x < 4; x++)
        for (int y = 0; y < 4; y++)
            for (int a = 0; a < 256; a++)
                for (int b = 0; b < 256; b++)
                    F[x][y][a][b] = f(((ll)a) << (8 * x), ((ll)b) << (8 * y));
    int t;
    cin >> t >> SA >> SB >> SC;
    int ans = 0;
    while (t--) {
        unsigned int x = rng() + ans;
        unsigned int y = rng();
        ans = nim_mul(x, y);
    }
    cout << ans << endl;
    return 0;
}